function legacyQuickStats(preview){
  const mapping=preview.mapping||{},get=(row,key)=>Number(mapping[key])>=0?String(row[Number(mapping[key])]??'').trim():'';
  let ok=0,units=0,value=0,skipped=0;const categories=new Set();
  for(const row of preview.grid){
    const name=get(row,'name'),quantity=importNumber(get(row,'quantity')),price=importNumber(get(row,'price'));
    if(!name||quantity===null||quantity<0||price===null||price<=0){skipped++;continue;}
    ok++;units+=quantity;value+=quantity*price;const category=get(row,'category');if(category)categories.add(category);
  }
  return {ok,units,value,skipped,categories:categories.size};
}
// After the owner signs in on an empty catalogue, look (quietly) for the old software's export and offer a one-click import.
async function maybePromptLegacy(){
  if(state.legacyPrompted||!state.user||state.user.role!=='owner')return;
  state.legacyPrompted=true;
  try{
    if(!state.overview||state.overview.productCount>0)return;
    const found=(await api('/api/legacy-export/scan')).candidates;
    if(!found.length)return;
    const top=found[0],key='pp-legacy-later:'+top.fileName+'|'+top.modifiedAt;
    try{if(localStorage.getItem(key))return;}catch(e){}
    const data=await api('/api/legacy-export?id='+encodeURIComponent(top.id));
    const binary=atob(data.contentBase64),bytes=new Uint8Array(binary.length);
    for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);
    const text=decodeCsvBuffer(bytes),preview=parseImportPreview(text,data.fileName),stats=legacyQuickStats(preview);
    if(!stats.ok||['name','price','quantity'].some(k=>Number(preview.mapping[k])<0))return;
    state.legacyQuick={candidate:top,data,text,preview,stats,key,busy:false};
    state.modal='legacy-quick';renderApp();
  }catch(e){/* the owner can still use the button on the Stock page */}
}
function legacyBanner(){
  const info=state.legacyInfo,list=state.legacyCandidates||[];
  if(state.products.length)return '';
  if(!list.length){
    if(!info)return `<div class="owner-import-note"><span><span class="spinner"></span></span><div><b>Recherche du stock de l’ancien logiciel…</b><small>Quelques secondes : bureau, documents, clés USB et dossier du logiciel.</small></div></div>`;
    const where=info.oldApp&&info.oldApp.length?`Ancien logiciel repéré : <b>${esc(info.oldApp[0])}</b>. `:'';
    return `<div class="owner-import-note" style="border-color:#c27a12;background:#fdf6e7"><span>${ico('triangle-alert',20)}</span><div><b>Fichier de stock de l’ancien logiciel non trouvé</b><small>${where}Dans l’ancien logiciel, exportez la liste des articles en CSV (Articles….csv) vers le Bureau ou une clé USB, puis relancez la recherche. ${info.deep?'La recherche approfondie a déjà été faite.':''}</small></div>${info.deep?'':'<button class="button secondary" data-action="legacy-deep">Recherche approfondie</button>'}<button class="button primary" data-action="legacy-rescan">Relancer</button></div>`;
  }
  const first=list[0];
  return `<div class="owner-import-note" style="border-color:#1d6b46;background:#e9f6ee"><span>${ico('file-check',20)}</span><div><b>Liste de l’ancien logiciel détectée</b><small>${esc(first.fileName)} · ${time(first.modifiedAt)} · ${esc(first.folder)}${list.length>1?` · ${list.length-1} autre(s) fichier(s) possible(s)`:''}</small></div><button class="button primary" data-action="${list.length>1?'detect-legacy-export':'legacy-load'}" data-id="${esc(first.id)}">Réviser et importer</button></div>`;
}
