  if(state.modal==='add-product'){title='Ajouter un produit';form='product-form';submit='Enregistrer le produit';body=`<div class="field"><label>Nom du produit</label><input name="name" required></div><div class="field"><label>Code-barres</label><input name="barcode"></div><div class="field"><label>Référence (SKU)</label><input name="sku"></div><div class="field"><label>Catégorie</label><input name="category"></div><div class="field"><label>Prix de vente MAD</label><input name="price" type="number" min="0" step="0.01" required></div><div class="field"><label>Coût d’achat MAD</label><input name="cost" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Quantité initiale</label><input name="quantity" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Seuil de réapprovisionnement</label><input name="reorderLevel" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Unité</label><input name="unit" value="unité"></div><div class="field"><label>Photo produit (URL HTTPS)</label><input name="imageUrl" type="url" placeholder="https://…"></div><div class="field"><label>Fournisseur</label><select name="supplierId"><option value="">Non renseigné</option>${state.suppliers.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select></div>`;}
  if(state.modal==='edit-product'&&state.editProduct){const p=state.editProduct;title='Modifier le produit';form='edit-product-form';submit='Enregistrer les modifications';body=`<div class="field"><label>Nom du produit</label><input name="name" required value="${esc(p.name)}"></div><div class="field"><label>Code-barres · touchez ce champ puis scannez la boîte</label><input name="barcode" value="${esc(p.barcode||'')}" autocomplete="off"></div><div class="field"><label>Catégorie</label><input name="category" value="${esc(p.category||'')}"></div><div class="field"><label>Prix de vente MAD</label><input name="price" type="number" min="0" step="0.01" required value="${(p.price_cents/100).toFixed(2)}"></div><div class="field"><label>Coût d’achat MAD</label><input name="cost" type="number" min="0" step="0.01" value="${((p.cost_cents||0)/100).toFixed(2)}"></div><div class="field"><label>Stock actuel (une correction est enregistrée dans l’historique)</label><input name="quantity" type="number" min="0" step="0.01" value="${p.quantity}"></div><div class="field"><label>Seuil de réapprovisionnement</label><input name="reorderLevel" type="number" min="0" step="0.01" value="${p.reorder_level}"></div><div class="field"><label>Unité</label><input name="unit" value="${esc(p.unit)}"></div>`;}
