function importNumber(value){const normalized=String(value??'').replace(/[\s\u00a0]/g,'').replace(',','.');return /^-?\d+(?:\.\d+)?$/.test(normalized)?Number(normalized):null;}
function importStats(preview){
  const mapping=preview.mapping||{},get=(row,key)=>Number(mapping[key])>=0?String(row[Number(mapping[key])]??'').trim():'',names=preview.grid.map(row=>get(row,'name')).filter(Boolean),keys=names.map(name=>name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('fr').replace(/[^a-z0-9]+/g,' ').trim()),groups=new Map();keys.forEach(key=>groups.set(key,(groups.get(key)||0)+1));
  const numbers=preview.grid.map(row=>({quantity:importNumber(get(row,'quantity')),price:importNumber(get(row,'price'))}));
  const existing=new Set(state.products.map(product=>product.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('fr').replace(/[^a-z0-9]+/g,' ').trim()));
  const invalidRowCount=preview.grid.filter(row=>{const name=get(row,'name'),quantity=importNumber(get(row,'quantity')),price=importNumber(get(row,'price')),cost=Number(mapping.cost)>=0?importNumber(get(row,'cost')):0,threshold=Number(mapping.threshold)>=0?importNumber(get(row,'threshold')):0;return !name||quantity===null||quantity<0||price===null||price<0||cost===null||cost<0||threshold===null||threshold<0;}).length;
  const valid=preview.grid.filter(row=>{const name=get(row,'name'),quantity=importNumber(get(row,'quantity')),price=importNumber(get(row,'price')),cost=Number(mapping.cost)>=0?importNumber(get(row,'cost')):0,threshold=Number(mapping.threshold)>=0?importNumber(get(row,'threshold')):0;return !!name&&quantity!==null&&quantity>=0&&price!==null&&price>=0&&cost!==null&&cost>=0&&threshold!==null&&threshold>=0&&(price!==0||preview.allowZeroSalePrice);});
  const seen=new Set();let eligibleCount=0;for(const row of preview.grid){const key=get(row,'name').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('fr').replace(/[^a-z0-9]+/g,' ').trim();if(key&&valid.includes(row)&&(preview.duplicatePolicy==='add_separate'||(!existing.has(key)&&!seen.has(key)))){eligibleCount++;seen.add(key);}}
  return {categoryCount:new Set(preview.grid.map(row=>get(row,'category')).filter(Boolean)).size,negativeQuantityCount:numbers.filter(value=>value.quantity!==null&&value.quantity<0).length,invalidRowCount,zeroSalePriceCount:numbers.filter(value=>value.price===0).length,duplicateNameGroups:[...groups.values()].filter(count=>count>1).length,matchesExisting:keys.filter(key=>existing.has(key)).length,eligibleCount};
}
async function openImportPreview(text,fileName,metadata={}){
  const preview=parseImportPreview(text,fileName);
  const staged=await api('/api/products/import/preview',{method:'POST',body:JSON.stringify({fileName,content:text})});
  preview.stageId=staged.stageId;preview.duplicate=staged.duplicate;preview.sourcePath=metadata.sourcePath||'';preview.modifiedAt=metadata.modifiedAt||'';
  state.importPreview=preview;state.modal='import-preview';renderApp();
}
function downloadTemplate(){const csv='Code-barres;Référence;Désignation;Catégorie;Unité;Quantité;Seuil;Prix vente;Coût achat;Image URL\r\n';const blob=new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='promedpara-modele-stock.csv';a.click();URL.revokeObjectURL(a.href);}
function exportProducts(){
  const headers=['Code-barres','Référence','Désignation','Catégorie','Unité','Quantité','Seuil','Prix vente','Coût achat','Image URL'];
  const quote=value=>`"${String(value??'').replace(/"/g,'""')}"`;
  const rows=state.products.map(p=>[p.barcode,p.sku,p.name,p.category,p.unit,p.quantity,p.reorder_level,(Number(p.price_cents||0)/100).toFixed(2).replace('.',','),(Number(p.cost_cents||0)/100).toFixed(2).replace('.',','),p.image_url||'']);
  const csv=[headers,...rows].map(row=>row.map(quote).join(';')).join('\r\n');
  const blob=new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download='promedpara-stock.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}

